+ priya:{name:'Priya Shah',short:'PRIYA',age:'27',job:'tattoo artist',pronouns:'she/her',color:'#d58c64',hair:'#171a24',skin:'#d9a782',eyes:'#53362d',tag:'THE ARTIST',sub:'Ink on her fingers',loc:'INK & OAK · OLD TOWN',traits:'Fearless · secretly sentimental · owns too many plants',intro:'Priya caps a pen and studies a sketchbook full of tiny, intricate worlds. She catches you looking and tilts it your way.',lines:[
