+function update(){const c=castData[state.person],s=state.stats[state.person],v=venues[state.venue];$('#dayLabel').textContent=`${days[Math.min(state.day,5)]} · ${state.hour>21?'LATE':'7 PM'}`;$('#energyLabel').textContent='●'.repeat(state.energy)+'○'.repeat(3-state.energy);$('#cashLabel').textContent=state.cash;$('#locationLabel').textContent=v.label;$('#clockLabel').textContent=`${['MONDAY','TUESDAY','WEDNESDAY','THURSDAY','FRIDAY','SATURDAY'][Math.min(state.day,5)]} · ${timeText()}`;$('#captionSub').textContent=v.kind.toUpperCase();$('#captionName').textContent=c.short;$('#sceneBadge').textContent=state.day>=4?'WEEKEND PLANS':'FIRST IMPRESSIONS';$('#cast').innerHTML=portrait(state.person);$('#miniPortrait').innerHTML=portrait(state.person);$('#personName').textContent=c.name;$('#personSub').textContent=`${c.age} · ${c.job} · ${c.pronouns}`;$('#routeTag').textContent=s.chem>=38&&s.trust>=30?'A SPARK':'GETTING TO KNOW';$('#chemistryVal').textContent=`${s.chem} / 100`;$('#trustVal').textContent=`${s.trust} / 100`;$('#chemistryFill').style.width=`${s.chem}%`;$('#trustFill').style.width=`${s.trust}%`;const hearts=Math.min(5,Math.floor(s.chem/20));$('#heartmeter').innerHTML=Array.from({length:5},(_,i)=>`<i class="${i<hearts?'on':''}">♥</i>`).join('');$('#dialogMeta').textContent=`${v.label.split('·')[0].trim()} · ${timeText()}`;renderTasks();renderInbox();setActionButtons();}
