function openVenue(){const html=`<div class="eyebrow">Pick your evening</div><h2>Where to?</h2><p>Different corners of the city, different people, different kinds of chemistry.</p><div class="modal-list">${Object.entries(venues).map(([k,v])=>`<button class="nav-button" style="width:100%;margin-bottom:7px" onclick="chooseVenue('${k}')">${castData[v.character].name} · ${v.label}<span>${v.desc}</span></button>`).join('')}</div><div class="modal-actions"><button class="secondary" onclick="closeModal()">STAY HERE</button></div>`;openModal(html)}
